fn sinf(a: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let i: i32 = (a >> 3) & 31;
    let f: i32 = a & 7;
    let s0: i32 = tab[i];
    let s1: i32 = tab[(i + 1) & 31];
    s0 + (s1 - s0) * f / 8
}

fn cosf(a: i32) -> i32 {
    sinf(a + 64)
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let pal = [0xff5577, 0xffaa33, 0x33ddff, 0x99ff66];
    host::display::clear(0x000008);
    let mut s: i32 = 0;
    while s < 512 {
        let x: i32 = cx + 110 * cosf(s) / 127 + 62 * cosf(s * 5 / 2 + t) / 127;
        let y: i32 = cy + 110 * sinf(s) / 127 - 62 * sinf(s * 5 / 2 + t) / 127;
        host::display::fill_rect(x, y, 2, 2, pal[(s >> 7) & 3]);
        s = s + 1;
    }
    host::display::present();
}
